// Font Roboto đã cắt gọn (chỉ giữ Latin + toàn bộ dấu tiếng Việt + ký hiệu
// thường dùng) — jsPDF không có sẵn font hỗ trợ tiếng Việt, PHẢI nhúng font
// riêng thì chữ có dấu mới ra đúng, không thì sẽ bị vỡ chữ (đã kiểm chứng
// thật bằng cách xuất thử 1 PDF rồi đọc lại đúng nội dung).
// Nguồn: Roboto (Google Fonts, Apache License 2.0), cắt gọn bằng fonttools.

export const ROBOTO_VN_REGULAR_BASE64 =
  "";

export const ROBOTO_VN_BOLD_BASE64 =
  "";

// Đăng ký font này vào 1 tài liệu jsPDF (cả 2 kiểu thường + đậm), rồi đặt
// làm font mặc định luôn — gọi đúng 1 lần ngay sau khi tạo `new jsPDF(...)`,
// trước khi gọi doc.text()/autoTable() ở bất cứ đâu khác.
export function dangKyFontVN(doc: {
  addFileToVFS: (path: string, data: string) => void;
  addFont: (path: string, name: string, style: string) => void;
  setFont: (name: string, style?: string) => void;
}): void {
  doc.addFileToVFS('Roboto-VN-Regular.ttf', ROBOTO_VN_REGULAR_BASE64);
  doc.addFont('Roboto-VN-Regular.ttf', 'RobotoVN', 'normal');
  doc.addFileToVFS('Roboto-VN-Bold.ttf', ROBOTO_VN_BOLD_BASE64);
  doc.addFont('Roboto-VN-Bold.ttf', 'RobotoVN', 'bold');
  doc.setFont('RobotoVN', 'normal');
}
